#include <arpa/inet.h>
#include <atomic>
#include <iostream>
#include <sqlite3.h>
#include <string>
#include <sys/socket.h>
#include <thread>
#include <unistd.h>
#include <vector>
#include "service.hpp"
bool send_all(int fd,const std::string& data){std::size_t sent=0;while(sent<data.size()){auto count=write(fd,data.data()+sent,data.size()-sent);if(count<=0)return false;sent+=static_cast<std::size_t>(count);}return true;}
int main(){int clients{},requestsPerClient{};if(!(std::cin>>clients>>requestsPerClient)||clients<1||clients>16||requestsPerClient<1||requestsPerClient>100)return 2;int total=clients*requestsPerClient;sqlite3* database{};if(sqlite3_open(":memory:",&database)!=SQLITE_OK)return 3;if(sqlite3_exec(database,"CREATE TABLE request_metrics(status INTEGER NOT NULL)",nullptr,nullptr,nullptr)!=SQLITE_OK)return 4;int server=socket(AF_INET,SOCK_STREAM,0);sockaddr_in address{};address.sin_family=AF_INET;address.sin_addr.s_addr=htonl(INADDR_LOOPBACK);address.sin_port=0;if(server<0||bind(server,reinterpret_cast<sockaddr*>(&address),sizeof(address))<0)return 5;socklen_t addressSize=sizeof(address);if(getsockname(server,reinterpret_cast<sockaddr*>(&address),&addressSize)<0||listen(server,128)<0)return 6;std::atomic<int> errors{0};std::thread acceptor([&]{for(int index=0;index<total;++index){int peer=accept(server,nullptr,nullptr);if(peer<0){errors.fetch_add(1);continue;}char buffer[256]{};auto count=read(peer,buffer,sizeof(buffer));std::string request(buffer,count>0?static_cast<std::size_t>(count):0);auto response=route(request.find("GET /health ")!=std::string::npos?"/health":"/missing");std::string wire="HTTP/1.1 "+std::to_string(response.status)+(response.status==200?" OK":" Not Found")+"\r\nContent-Length: "+std::to_string(response.body.size())+"\r\nConnection: close\r\n\r\n"+response.body;if(!send_all(peer,wire))errors.fetch_add(1);if(sqlite3_exec(database,("INSERT INTO request_metrics VALUES("+std::to_string(response.status)+")").c_str(),nullptr,nullptr,nullptr)!=SQLITE_OK)errors.fetch_add(1);close(peer);}});std::vector<std::thread> workers;for(int clientIndex=0;clientIndex<clients;++clientIndex)workers.emplace_back([&]{for(int requestIndex=0;requestIndex<requestsPerClient;++requestIndex){int client=socket(AF_INET,SOCK_STREAM,0);if(client<0||connect(client,reinterpret_cast<sockaddr*>(&address),sizeof(address))<0){errors.fetch_add(1);if(client>=0)close(client);continue;}std::string request="GET /health HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n";if(!send_all(client,request)){errors.fetch_add(1);close(client);continue;}char response[256]{};auto count=read(client,response,sizeof(response));if(count<=0||std::string(response,static_cast<std::size_t>(count)).find("HTTP/1.1 200")!=0)errors.fetch_add(1);close(client);}});for(auto& worker:workers)worker.join();acceptor.join();sqlite3_stmt* statement{};int stored=-1;if(sqlite3_prepare_v2(database,"SELECT COUNT(*) FROM request_metrics",-1,&statement,nullptr)==SQLITE_OK&&sqlite3_step(statement)==SQLITE_ROW)stored=sqlite3_column_int(statement,0);sqlite3_finalize(statement);sqlite3_close(database);close(server);std::cout<<"requests="<<total<<" errors="<<errors.load()<<" stored="<<stored<<'\n';}

